{
  "task": "format_questions_to_latex",
  "questions": [
    {
      "source_id": "1",
      "stem": "A survey drone starts at the origin of a coordinate grid and detects a beacon at position \\(\\vec r = -7\\hat i + 24\\hat j\\), where distances are measured in kilometers. Which of the following statements is correct?",
      "options": [
        {
          "key": "A",
          "text": "The distance from the drone to the beacon is \\(31\\) km.",
          "is_correct": false,
          "explanation": "This comes from adding the magnitudes of the components, \\(7+24\\), instead of finding the vector magnitude. Distance from the origin must be computed with \\(|\\vec r|=\\sqrt{x^2+y^2}\\), not by simple addition."
        },
        {
          "key": "B",
          "text": "The distance from the drone to the beacon is \\(25\\) km.",
          "is_correct": true,
          "explanation": "The beacon's position vector has components \\(-7\\) km and \\(24\\) km, so its distance from the origin is the magnitude \\(|\\vec r|=\\sqrt{(-7)^2+24^2}=\\sqrt{49+576}=\\sqrt{625}=25\\,\\mathrm{km}\\). The sign of the \\(x\\)-component affects direction but not the distance, so the correct choice is \\(25\\) km."
        },
        {
          "key": "C",
          "text": "The distance from the drone to the beacon is \\(24\\) km.",
          "is_correct": false,
          "explanation": "This treats only the vertical component as the full distance. Both the \\(x\\)- and \\(y\\)-components contribute to the magnitude of the position vector."
        },
        {
          "key": "D",
          "text": "The distance from the drone to the beacon is \\(7\\) km.",
          "is_correct": false,
          "explanation": "This uses only the horizontal component and ignores the vertical displacement. A vector's magnitude must include all perpendicular components through the Pythagorean relation."
        }
      ],
      "question_type": "multiple_choice",
      "skipped": false,
      "skip_reason": "",
      "answer": "",
      "parts": []
    },
    {
      "source_id": "2",
      "stem": "The position of a particle moving along the \\(x\\)-axis is given by \\(\\vec s(t)=\\big((0.80\\,\\mathrm{m/s^3})t^3-(1.90\\,\\mathrm{m/s^2})t^2\\big)\\hat i\\). Which of the following statements is correct?",
      "options": [
        {
          "key": "A",
          "text": "The magnitude of the acceleration at \\(t=0\\) is \\(3.8\\,\\mathrm{m/s^2}\\).",
          "is_correct": true,
          "explanation": "Differentiate twice: \\(\\vec v(t)=\\big(2.40t^2-3.80t\\big)\\hat i\\) and \\(\\vec a(t)=\\big(4.80t-3.80\\big)\\hat i\\). At \\(t=0\\), the acceleration is \\(-3.80\\hat i\\,\\mathrm{m/s^2}\\), so its magnitude is \\(3.8\\,\\mathrm{m/s^2}\\)."
        },
        {
          "key": "B",
          "text": "This motion has constant acceleration.",
          "is_correct": false,
          "explanation": "This error comes from overlooking the cubic term in position. Since \\(\\vec a(t)=\\big(4.80t-3.80\\big)\\hat i\\), the acceleration depends on time and is not constant."
        },
        {
          "key": "C",
          "text": "The magnitude of the acceleration is \\(1.9\\,\\mathrm{m/s^2}\\).",
          "is_correct": false,
          "explanation": "This confuses the coefficient of the \\(t^2\\) term in displacement with acceleration itself. Acceleration must be obtained from the second derivative of the displacement function."
        },
        {
          "key": "D",
          "text": "The magnitude of the acceleration at \\(t=0\\) is \\(0\\,\\mathrm{m/s^2}\\).",
          "is_correct": false,
          "explanation": "This mistake assumes the acceleration must vanish initially. Evaluating \\(\\vec a(t)=\\big(4.80t-3.80\\big)\\hat i\\) at \\(t=0\\) gives a nonzero value."
        }
      ],
      "question_type": "multiple_choice",
      "skipped": false,
      "skip_reason": "",
      "answer": "",
      "parts": []
    },
    {
      "source_id": "3",
      "stem": "A robot moves from position \\(\\vec r_A = 1\\hat i - 2\\hat j\\) m to position \\(\\vec r_B = 7\\hat i + 6\\hat j\\) m in \\(5.0\\) s. Which of the following statements is correct?",
      "options": [
        {
          "key": "A",
          "text": "The robot must have traveled a distance of \\(10\\) m.",
          "is_correct": false,
          "explanation": "The value \\(10\\,\\mathrm{m}\\) is the magnitude of the displacement, not necessarily the path length traveled. The actual distance traveled depends on the path and cannot be determined from only the initial and final positions."
        },
        {
          "key": "B",
          "text": "The robot's speed at \\(t=0\\) must have been \\(2.0\\,\\mathrm{m/s}\\).",
          "is_correct": false,
          "explanation": "This comes from dividing displacement magnitude by elapsed time and interpreting that as the initial speed. Endpoint positions over a time interval do not uniquely determine the speed at the starting instant."
        },
        {
          "key": "C",
          "text": "The magnitude of the displacement is \\(10\\) m.",
          "is_correct": true,
          "explanation": "The displacement is \\(\\Delta\\vec r=\\vec r_B-\\vec r_A=(7-1)\\hat i + \\big(6-(-2)\\big)\\hat j = 6\\hat i+8\\hat j\\,\\mathrm{m}\\). Its magnitude is \\(|\\Delta\\vec r|=\\sqrt{6^2+8^2}=\\sqrt{100}=10\\,\\mathrm{m}\\), so this is the only statement that must be true."
        },
        {
          "key": "D",
          "text": "The robot's acceleration at \\(t=0\\) must have been \\(0.40\\,\\mathrm{m/s^2}\\).",
          "is_correct": false,
          "explanation": "This incorrectly assumes acceleration can be inferred from displacement and total time alone. Without more information about the motion or velocity, the initial acceleration is not determined."
        }
      ],
      "question_type": "multiple_choice",
      "skipped": false,
      "skip_reason": "",
      "answer": "",
      "parts": []
    }
